import getpass
import os
import sys
from django.contrib.auth import get_user_model
from django.contrib.auth.management import get_default_username
from django.contrib.auth.password_validation import validate_password
from django.core import exceptions
from django.core.management.base import BaseCommand, CommandError
from django.db import DEFAULT_DB_ALIAS
from django.utils.text import capfirst
from dashboard.models import Organization  # Import the Organization model

class NotRunningInTTYException(Exception):
    pass

PASSWORD_FIELD = 'password'

class Command(BaseCommand):
    help = 'Used to create a superuser.'
    requires_migrations_checks = True
    stealth_options = ('stdin',)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.UserModel = get_user_model()
        self.username_field = self.UserModel._meta.get_field(self.UserModel.USERNAME_FIELD)

    def add_arguments(self, parser):
        parser.add_argument('--%s' % self.UserModel.USERNAME_FIELD, help='Specifies the login for the superuser.')
        parser.add_argument('--noinput', '--no-input', action='store_false', dest='interactive', help='No interactive input.')
        parser.add_argument('--database', default=DEFAULT_DB_ALIAS, help='Specifies the database to use.')
        parser.add_argument('--organization', help='Specifies the organization for the superuser.')  # Add organization option

        for field_name in self.UserModel.REQUIRED_FIELDS:
            field = self.UserModel._meta.get_field(field_name)
            parser.add_argument('--%s' % field_name, help='Specifies the %s for the superuser.' % field_name)

    def handle(self, *args, **options):
        username = options[self.UserModel.USERNAME_FIELD]
        database = options['database']
        user_data = {}

        verbose_field_name = self.username_field.verbose_name
        try:
            self.UserModel._meta.get_field(PASSWORD_FIELD)
            user_data[PASSWORD_FIELD] = None
        except exceptions.FieldDoesNotExist:
            pass

        if options['interactive']:
            organization = options.get('organization')
            if not organization:
                organizations = Organization.objects.all()
                if organizations.exists():
                    self.stdout.write("Available organizations:")
                    for org in organizations:
                        self.stdout.write(f"- {org.name}")
                    organization_name = input("Enter organization name: ")
                    try:
                        organization = Organization.objects.get(name=organization_name)
                    except Organization.DoesNotExist:
                        raise CommandError(f"Organization '{organization_name}' does not exist.")
                else:
                    raise CommandError("No organizations found. Please create one first.")

            # Prompt for username
            if username:
                error_msg = self._validate_username(username, verbose_field_name, database)
                if error_msg:
                    self.stderr.write(error_msg)
                    username = None
            elif username == '':
                raise CommandError('%s cannot be blank.' % capfirst(verbose_field_name))
            while username is None:
                message = self._get_input_message(self.username_field, get_default_username(database=database))
                username = self.get_input_data(self.username_field, message, get_default_username(database=database))
                if username:
                    error_msg = self._validate_username(username, verbose_field_name, database)
                    if error_msg:
                        self.stderr.write(error_msg)
                        username = None
                        continue
            user_data[self.UserModel.USERNAME_FIELD] = username

            # Prompt for required fields
            for field_name in self.UserModel.REQUIRED_FIELDS:
                field = self.UserModel._meta.get_field(field_name)
                user_data[field_name] = options[field_name]
                while user_data[field_name] is None:
                    message = self._get_input_message(field)
                    input_value = self.get_input_data(field, message)
                    user_data[field_name] = input_value
                    if field.many_to_many and input_value:
                        if not input_value.strip():
                            user_data[field_name] = None
                            self.stderr.write('Error: This field cannot be blank.')
                            continue
                        user_data[field_name] = [pk.strip() for pk in input_value.split(',')]

            # Prompt for a password
            while PASSWORD_FIELD in user_data and user_data[PASSWORD_FIELD] is None:
                password = getpass.getpass()
                password2 = getpass.getpass('Password (again): ')
                if password != password2:
                    self.stderr.write("Error: Your passwords didn't match.")
                    continue
                if password.strip() == '':
                    self.stderr.write("Error: Blank passwords aren't allowed.")
                    continue
                try:
                    validate_password(password2, self.UserModel(**user_data))
                except exceptions.ValidationError as err:
                    self.stderr.write('\n'.join(err.messages))
                    response = input('Bypass password validation and create user anyway? [y/N]: ')
                    if response.lower() != 'y':
                        continue
                user_data[PASSWORD_FIELD] = password
        else:
            # Non-interactive mode
            if PASSWORD_FIELD in user_data and 'DJANGO_SUPERUSER_PASSWORD' in os.environ:
                user_data[PASSWORD_FIELD] = os.environ['DJANGO_SUPERUSER_PASSWORD']
            if username is None:
                username = os.environ.get('DJANGO_SUPERUSER_' + self.UserModel.USERNAME_FIELD.upper())
            if username is None:
                raise CommandError('You must use --%s with --noinput.' % self.UserModel.USERNAME_FIELD)
            else:
                error_msg = self._validate_username(username, verbose_field_name, database)
                if error_msg:
                    raise CommandError(error_msg)
            user_data[self.UserModel.USERNAME_FIELD] = username
            for field_name in self.UserModel.REQUIRED_FIELDS:
                env_var = 'DJANGO_SUPERUSER_' + field_name.upper()
                value = options[field_name] or os.environ.get(env_var)
                if not value:
                    raise CommandError('You must use --%s with --noinput.' % field_name)
                field = self.UserModel._meta.get_field(field_name)
                user_data[field_name] = field.clean(value, None)

        # Create the superuser with an organization
        superuser = self.UserModel._default_manager.db_manager(database).create_superuser(**user_data)
        superuser.organization = organization  # Set the organization
        superuser.save()

        if options['verbosity'] >= 1:
            self.stdout.write("Superuser created successfully with organization.")

    def get_input_data(self, field, message, default=None):
        raw_value = input(message)
        if default and raw_value == '':
            raw_value = default
        try:
            val = field.clean(raw_value, None)
        except exceptions.ValidationError as e:
            self.stderr.write("Error: %s" % '; '.join(e.messages))
            val = None
        return val

    def _get_input_message(self, field, default=None):
        return '%s%s%s: ' % (
            capfirst(field.verbose_name),
            " (leave blank to use '%s')" % default if default else '',
            ' (%s.%s)' % (
                field.remote_field.model._meta.object_name,
                field.m2m_target_field_name() if field.many_to_many else field.remote_field.field_name,
            ) if field.remote_field else '',
        )

    def _validate_username(self, username, verbose_field_name, database):
        if self.username_field.unique:
            try:
                self.UserModel._default_manager.db_manager(database).get_by_natural_key(username)
            except self.UserModel.DoesNotExist:
                pass
            else:
                return 'Error: That %s is already taken.' % verbose_field_name
        if not username:
            return '%s cannot be blank.' % capfirst(verbose_field_name)
        try:
            self.username_field.clean(username, None)
        except exceptions.ValidationError as e:
            return '; '.join(e.messages)